  /* Wrappers stay transparent. The <img> itself carries a white disc that opaque
     JPEGs hide but transparent PNGs do not. */
  .avatar, .avatarWrapper, .contentRow-figure,
  .structItem-iconContainer, .avatar img { background-color: transparent !important; }
  /* XenForo paints a per-user chip via inline style; the transparent rule above
     erases it and the broad link colour repaints the initial. Do NOT restore the
     inline pair: that palette is built for a light page and half of it IS light,
     which would scatter bright discs down every thread row. `a.avatar--default` must
     stay at least as specific as `.p-body-content a`. */
  .avatar--default, a.avatar--default {
    background-color: #21262d !important;
    color: #c4d3e8 !important;
    -webkit-text-fill-color: #c4d3e8 !important;
  }
}
